from lib import *
S = SS('p15')
steps = [
    step("同一段中文(爬虫工程:…镕。)放在不同声明的页面里。UTF-8 页面 + Content-Type: text/html; charset=utf-8:r.encoding='utf-8',r.text 正确。UTF-8 页面 + Content-Type: text/html(没写 charset):r.encoding 变成 'ISO-8859-1',r.text 是乱码(ç¬è«…),r.apparent_encoding 其实猜对了 utf-8。Content-Type 换成 application/octet-stream:r.encoding=None,r.text 反而是对的(没有默认编码时 requests 用 apparent_encoding)。GBK 页面 + <meta charset=\"gbk\"> 但响应头没写:r.text 乱码(ISO-8859-1),lxml.html.fromstring(r.content) 按 meta 解出正确文字;GBK 页面 + 响应头 charset=gbk:r.text 正确,lxml 因为页面里没有 meta 而乱码。requests 不看 meta,lxml 不看响应头。", t=tl(S(1)), done=lidx(S(1), 'Content-Type=\'text/html; charset=gbk\'', 'application/octet-stream', "charset=utf-8';r.encoding='utf-8'"), mark=lidx(S(1), "r.encoding='ISO-8859-1'"), kv=KV([['text/* 没写 charset', 'requests 默认 ISO-8859-1'], ['非 text/*', 'r.encoding=None,用猜测的'], ['requests 与 lxml', '一个看响应头,一个看 meta']], ['text/* 没写 charset'])),
    step("声明和实际不一致时:响应头说 gbk、页面实际是 UTF-8(meta 写 utf-8):r.text 乱码(鐖�铏�…),lxml 按 meta 解对;响应头说 utf-8、页面实际是 GBK(meta 写 gbk):r.text 满是 U+FFFD,lxml 按 meta 解对。最麻烦的是页面声明 gb2312、实际是 GBK、含 GB2312 里没有的字(这里是“镕”):Python 用 gb2312 解码,“镕”变成替换字符 + F;用 gbk、gb18030 解码一致;lxml 按 meta 的 gb2312 解码,文字在这个字符处中断,结尾变成 F-8,(后面的“镕。”全丢了)。", t=tl(S(2)), done=lidx(S(2), '用 gbk 解码', '用 gb18030 解码'), mark=lidx(S(2), '用 gb2312 解码', '响应头没写,<meta charset="gb2312">', 'F-8,'), kv=KV([['gb2312 声明 + GBK 内容', 'gb2312 解不出“镕”'], ['lxml 的结果', '在该字处截断'], ['解法', '把 gb2312 当 gbk / gb18030 解码']], ['gb2312 声明 + GBK 内容'])),
    step("修正办法(UTF-8 页面,响应头只写 text/html):默认 r.text 是乱码;r.encoding = r.apparent_encoding(utf-8)之后正确;直接对字节 r.content.decode(\"utf-8\") 也正确;交给 lxml 字节但页面没有 meta 时,lxml 仍然乱码。另外把 r.text(字符串)交给 lxml 时,如果文档开头带 XML 编码声明,会抛 ValueError: Unicode strings with encoding declaration are not supported。", t=tl(S(3)), done=lidx(S(3), 'r.encoding = r.apparent_encoding', '自己对字节解码'), mark=lidx(S(3), '默认 r.text', 'ValueError'), kv=KV([['r.apparent_encoding', '给 r.encoding 赋值即可纠正'], ['r.content.decode', '最直接,可控'], ['lxml + 字符串', '有 XML 声明会 ValueError']], ['r.content.decode'])),
    step("UTF-8 BOM:响应体以 EF BB BF 开头,Content-Type: charset=utf-8 时 r.encoding='utf-8',r.text 的第一个字符是 \\ufeff(BOM 被当成字符),开头变成 '\\ufeff<h';用 utf-8-sig 解码才会去掉,得到 '<ht'。如果拿 r.text 的开头去判断 '<html' 或做 JSON 解析,会被这个看不见的字符绊倒。", t=tl(S(4)), done=lidx(S(4), 'utf-8-sig'), mark=lidx(S(4), '\\ufeff'), kv=KV([['utf-8', '保留 BOM 字符'], ['utf-8-sig', '去掉 BOM'], ['后果', '开头多一个看不见的字符']], ['后果'])),
    step("猜编码有多准(charset_normalizer 3.4.9,requests 的 apparent_encoding 用的就是它):36 个“语言 × 编码 × 句数”组合里,猜得和真实编码名字不同的有 13 个,但多数是兼容的超集(GBK 被猜成 gb18030,Shift_JIS 被猜成 cp932,EUC-KR 被猜成 cp949),解出来的文字没问题;真正解出错文字的只有 3 个:日文 EUC-JP 的 1 句被猜成 cp949;法文 latin-1 的 1 句被猜成 cp1250、3 句被猜成 big5。UTF-8 的 15 个组合全部猜对。", t=tl(S(5)), done=lidx(S(5), '检测出编码后用它解码', '共 36 个组合'), mark=lidx(S(5), 'euc_jp', 'latin-1'), b=bars([['组合总数', 36, '36'], ['名字猜得不同', 13, '13'], ['解出文字不对', 3, '3']], 36, mark=[2], done=[0]), kv=KV([['名字不同', '13 / 36,多数是超集'], ['文字不对', '3 / 36'], ['UTF-8', '全部猜对']], ['文字不对'])),
]
A = mkartp('p15', 15, '爬虫,编码,charset,requests,apparent_encoding,GBK,乱码,lxml,Python,真实验证,动画演示',
    '实测爬虫里乱码的来源:text/* 没写 charset 时 requests 默认 ISO-8859-1(r.apparent_encoding 其实能猜对 utf-8);requests 不看 meta,lxml 不看响应头;页面声明 gb2312 但含“镕”时 Python 解码替换、lxml 截断;UTF-8 BOM 变成 r.text 开头的 \\ufeff;charset_normalizer 36 个组合里有 3 个解错文字。',
    '爬虫拿到的网页乱码,往往不是页面坏了,而是你和服务器对“这段字节是什么编码”有不同的答案。这篇用本机服务器逐一复现:响应头、meta、实际字节三者不一致时 requests 和 lxml 分别怎么选,猜编码的库有多准。',
    [('ISO-8859-1', 'Content-Type: text/html 没写 charset 时,r.encoding 的默认值(UTF-8 页面因此变乱码)'), ('13 / 36 与 3 / 36', 'charset_normalizer 猜得名字不同的组合数,和解码后文字真正出错的组合数'), ('镕', 'GB2312 里没有的字:页面声明 gb2312 时,lxml 解码在这里中断')],
    [('谁说了算:响应头、meta、检测', '<p>requests 的 <code>r.encoding</code> 来自响应头;<code>text/*</code> 类型没写 <code>charset</code> 时是 <code>ISO-8859-1</code>,于是 UTF-8 页面成了乱码,尽管 <code>r.apparent_encoding</code> 已经猜出了 <code>utf-8</code>。非 <code>text/*</code> 类型(如 <code>application/octet-stream</code>)的 <code>r.encoding</code> 是 <code>None</code>,<code>r.text</code> 反而会用猜测值。requests 不读 HTML 里的 <code>&lt;meta charset&gt;</code>,lxml 解析字节时读 meta、不看响应头。</p>'),
     ('声明与实际不一致', '<p>响应头与实际字节不一致时 <code>r.text</code> 乱码;而用 lxml 解字节、页面有 meta 时能解对。GB2312 的字符集比 GBK 小:页面声明 <code>gb2312</code> 但包含“镕”这样的 GBK 字符,Python 的 gb2312 解码会把它替换掉,lxml 则在该字符处截断了后面的内容。把声明为 gb2312 的页面当 gbk 或 gb18030 解码更安全。</p>'),
     ('怎么修', '<p>最直接的办法:自己对 <code>r.content</code> 解码(比如先试 utf-8,失败再试 gb18030),或把 <code>r.encoding</code> 设成 <code>r.apparent_encoding</code>。给 lxml 传字节而不是字符串,但页面没有 meta 时它也会乱码;给 lxml 传字符串且文档带 XML 编码声明会抛 <code>ValueError</code>。</p>'),
     ('UTF-8 BOM', '<p>响应体开头的 BOM 在 <code>utf-8</code> 解码后变成 <code>\\ufeff</code> 字符,留在 <code>r.text</code> 开头;用 <code>utf-8-sig</code> 解码才会去掉。</p>'),
     ('猜编码有多准', '<p>用 <code>charset_normalizer</code> 对简体/繁体中文、日文、韩文、法文各取 1/3/10 句,36 个组合里 UTF-8 全对;名字不同的 13 个多是超集(GBK→gb18030、Shift_JIS→cp932、EUC-KR→cp949),文字没错;真正解错的 3 个是 EUC-JP 的 1 句(被猜成 cp949)和 latin-1 的 1 句、3 句(被猜成 cp1250、big5)。样本是我手写的十句,不代表真实网页的统计。</p>')],
    steps,
    [ENV_P + '。页面由本机服务器按指定 Content-Type 和字节发出;lxml 6.1.1 的 html.fromstring;检测用 charset_normalizer 3.4.9(requests 2.34.2 当前使用的检测库);五种语言各 10 句手写句子,取前 1、3、10 句拼接后用指定编码编码再检测',
     '没有验证:chardet、cchardet 等其它检测库的准确率;真实网页(含大量标签、脚本、英文混杂)的检测准确率;浏览器自己的编码嗅探规则(HTML 标准里的优先级与回退);BeautifulSoup、parsel 等库的编码处理(没有安装);meta 里 http-equiv 写法;GBK 之外 Big5-HKSCS、GB18030 四字节字符的行为'],
    '编码识别与乱码')
